window.products.push({"id":529111,"name":"Sleep Restoration Luxury Soft Brushed Embroidered Microfiber Duvet Cover Set with Beautiful Trim & Embroidery Details - King/Cal King - Cream/Gold","category":"homeandappliances","retail price":0.0,"sale price":null,"image":"https://m.media-amazon.com/images/I/71oM9E1L6ZL._AC_SL1500_.jpg","description":"Add a sophisticated touch to any room with the Sleep Restoration Ultra-Soft 3 Piece Embroidered Duvet Set. Crafted in 100% double brushed microfiber fabric, our duvet set is luxurious, durable and features custom designed embroidery work to pull any room together! It is extremely soft and will keep you comfortable all night long. Simply insert your duvet/comforter, secure with the corner ties, and zip the cover closed for a fashionable bed set that not only looks great, but feels cozy too!","images":["https://m.media-amazon.com/images/I/71oM9E1L6ZL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/61zNIJh6ZCL._SL1500_.jpg","https://m.media-amazon.com/images/I/61TWUez1VxL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51TIpnkrEpL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51I6jTu8yCL._AC_SL1300_.jpg","https://m.media-amazon.com/images/I/31o9GyU6jnL._AC_.jpg"],"specifications":{"brand":"Sleep Restoration","source_asin":"B073FRT3S6","category_path":"Home & Kitchen"},"sku":"BM-529111","productType":"Home & Appliances","inventory":0,"age_group":"Adult","gender":"Unisex","source_url":"https://www.amazon.com/dp/B073FRT3S6","source_catalog":"Amazon Reviews 2023 product metadata","source_file":"meta_Home_and_Kitchen_2023.jsonl","source_asin":"B073FRT3S6","price_pending":true,"merchant_ready":false});
